CREATE SCHEMA business_configuration;
CREATE TABLE business_configuration.dictionary_drafts(dictionary_id varchar(128) PRIMARY KEY,owner_module varchar(128) NOT NULL,revision integer NOT NULL CHECK(revision>0),items jsonb NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE business_configuration.dictionary_releases(dictionary_id varchar(128) NOT NULL,release_version integer NOT NULL CHECK(release_version>0),owner_module varchar(128) NOT NULL,content_digest varchar(64) NOT NULL CHECK(length(content_digest)=64),items jsonb NOT NULL,published_at timestamptz NOT NULL,PRIMARY KEY(dictionary_id,release_version));
CREATE TABLE business_configuration.parameter_definitions(parameter_key varchar(128) PRIMARY KEY,definition jsonb NOT NULL);
CREATE TABLE business_configuration.parameter_values(parameter_key varchar(128) NOT NULL,value_version integer NOT NULL CHECK(value_version>0),content_digest varchar(64) NOT NULL CHECK(length(content_digest)=64),value jsonb NOT NULL,published_at timestamptz NOT NULL,PRIMARY KEY(parameter_key,value_version),FOREIGN KEY(parameter_key) REFERENCES business_configuration.parameter_definitions(parameter_key));
CREATE TABLE business_configuration.parameter_activations(activation_id uuid PRIMARY KEY,parameter_key varchar(128) NOT NULL,value_version integer NOT NULL,scope_type varchar(128) NOT NULL,scope_reference varchar(255) NOT NULL,effective_from timestamptz NOT NULL,effective_to timestamptz,UNIQUE(activation_id,parameter_key),CHECK(effective_to IS NULL OR effective_from<effective_to),FOREIGN KEY(parameter_key,value_version) REFERENCES business_configuration.parameter_values(parameter_key,value_version));
CREATE INDEX configuration_activation_resolution_idx ON business_configuration.parameter_activations(parameter_key,scope_type,scope_reference,effective_from,effective_to);
CREATE TABLE business_configuration.parameter_activation_terminations(termination_id uuid PRIMARY KEY,activation_id uuid NOT NULL UNIQUE,parameter_key varchar(128) NOT NULL,effective_to timestamptz NOT NULL,occurred_at timestamptz NOT NULL,CHECK(effective_to>=occurred_at),FOREIGN KEY(activation_id,parameter_key) REFERENCES business_configuration.parameter_activations(activation_id,parameter_key));
CREATE TABLE business_configuration.operation_receipts(operation_id uuid PRIMARY KEY,fingerprint varchar(64) NOT NULL CHECK(length(fingerprint)=64),result jsonb NOT NULL);
CREATE TABLE business_configuration.outbox_events(event_id uuid PRIMARY KEY,event_type varchar(80) NOT NULL,resource_id varchar(128) NOT NULL,resource_version integer NOT NULL CHECK(resource_version>=0),occurred_at timestamptz NOT NULL,published_at timestamptz,last_error text);
CREATE FUNCTION business_configuration.reject_published_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'published configuration is immutable' USING ERRCODE='55000'; END $$;
CREATE TRIGGER dictionary_releases_no_update_delete BEFORE UPDATE OR DELETE ON business_configuration.dictionary_releases FOR EACH ROW EXECUTE FUNCTION business_configuration.reject_published_mutation();
CREATE TRIGGER parameter_definitions_no_update_delete BEFORE UPDATE OR DELETE ON business_configuration.parameter_definitions FOR EACH ROW EXECUTE FUNCTION business_configuration.reject_published_mutation();
CREATE TRIGGER parameter_values_no_update_delete BEFORE UPDATE OR DELETE ON business_configuration.parameter_values FOR EACH ROW EXECUTE FUNCTION business_configuration.reject_published_mutation();
CREATE TRIGGER parameter_activations_no_update_delete BEFORE UPDATE OR DELETE ON business_configuration.parameter_activations FOR EACH ROW EXECUTE FUNCTION business_configuration.reject_published_mutation();
CREATE TRIGGER parameter_activation_terminations_no_update_delete BEFORE UPDATE OR DELETE ON business_configuration.parameter_activation_terminations FOR EACH ROW EXECUTE FUNCTION business_configuration.reject_published_mutation();
